const plan = Object.freeze({ seats: 4 });

const attempts = [
  () => new Proxy(plan, { get: () => 10 }).seats,
  () => "seats" in new Proxy(plan, { has: () => false }),
  () => new Proxy({ seats: 4 }, { get: () => 10 }).seats,
  () => new Proxy(new Map(), {}).size,
];

for (const attempt of attempts) {
  try {
    console.log(attempt());
  } catch (error) {
    console.log(error.name);
  }
}
